{"path": "variable_length_quantity.py", "content": "def encode(numbers):
    """Encode a list of unsigned 32-bit integers into VLQ bytes."""
    result = []
    for number in numbers:
        if number < 0 or number > 0xFFFFFFFF:
            raise ValueError("number out of range for 32-bit unsigned integer")
        chunk = [number & 0x7F]
        number >>= 7
        while number:
            chunk.append((number & 0x7F) | 0x80)
            number >>= 7
        result.extend(reversed(chunk))
    return result


def decode(bytes_):
    """Decode a list of VLQ bytes into a list of integers."""
    values = []
    current = 0
    in_progress = False
    for byte in bytes_:
        current = (current << 7) | (byte & 0x7F)
        if byte & 0x80:
            in_progress = True
        else:
            values.append(current)
            current = 0
            in_progress = False
    if in_progress:
        raise ValueError("incomplete sequence")
    return values
